{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C09","C29","C19","C33","C35","C37","C38","C32","C34","C40","C41","C44","C45","C54","C55","C56","C58","C60","C61","C63","C64","C65","C68","C74"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C09","C29","C19","C33","C35","C37","C38","C32","C34","C40","C41","C68","C74"],
  "claims": [
    {
      "claim": "The query is a close linezolid analog sharing the 2-oxazolidinone core and N-aryl morpholine/morpholinone motif; linezolid has measured absolute oral bioavailability of 93.01 ± 23.34% after 600 mg tablets in fasted healthy subjects, is reported as almost 100% bioavailable in fasted healthy volunteers, and the tablet is highly bioavailable relative to IV.",
      "card_ids": ["C09","C29","C19"]
    },
    {
      "claim": "L3 oral exposure records for linezolid show substantial systemic exposure after oral dosing (median Cmax 18.3–18.9 µg/mL at 600 mg daily; mean Cmax 11.9 mg/L in elderly patients; AUCtau 99.2 µg·h/mL after 500 mg multiple dosing), consistent with high oral absorption.",
      "card_ids": ["C33","C35","C37","C38"]
    },
    {
      "claim": "Tedizolid, another oxazolidinone, achieved oral AUC 20.4–26.1 µg·h/mL versus IV 23.5–30.5 µg·h/mL and oral Cmax 2.25 versus IV 3.02 µg/mL after 200 mg phosphate prodrug, indicating oral exposure approximately 75–91% of IV and supporting class-level high oral bioavailability.",
      "card_ids": ["C32","C34","C40","C41"]
    },
    {
      "claim": "L4/L5 permeability records for morpholine-containing small molecules show high Caco-2 permeability with no or low efflux where reported (Papp roughly 21–43 ×10^-6 cm/s; ER 0.55–1.3), weakly supporting favorable intestinal absorption for the query's scaffold, though these records are not query-specific.",
      "card_ids": ["C44","C45","C54","C55","C56","C58","C60","C61","C63","C64","C65"]
    },
    {
      "claim": "L6 hepatic-clearance records for linezolid show only modest metabolic turnover (recombinant CYP3A4 CLint for desethylenelinezolid formation 1.12 µL/min/nmol P450; HLM CLint for 2-hydroxylation and desethylenation similar), consistent with low first-pass loss and supporting high oral bioavailability for the close linezolid analog; no query-specific high-clearance record is present.",
      "card_ids": ["C68","C74"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C66","C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "The query differs from linezolid at the amide substituent (5-chlorothiophene-2-carbonyl vs acetyl), the morpholine ring (3-one vs unsubstituted), and the absence of the aryl fluorine; these changes could affect absorption, solubility, or first-pass metabolism.",
    "No query-specific experimental solubility, permeability, efflux, or metabolic stability data are available; L4/L5/L6 records are for other scaffolds or for linezolid itself and cannot directly establish query absorption or presystemic loss.",
    "The query's prandial state and formulation are unspecified, while the closest linezolid F values were obtained under fasted conditions with tablets.",
    "L6 hepatic-clearance records are mechanistic and not direct oral-bioavailability results; only the linezolid metabolic-stability records transfer moderately to the query."
  ],
  "decision_summary": "Prediction remains high: the query is a close linezolid analog, and linezolid has measured absolute F of 93.01 ± 23.34% and is reported almost 100% bioavailable; L3 oral exposure records for linezolid and tedizolid support high oral bioavailability, and L6 linezolid metabolic-stability records show modest hepatic turnover, supporting low first-pass loss. No affirmative evidence supports F <20%, so the high prediction is strengthened."
}

